    /**
     * Method to retrieve the Clinician via an ClinicianPrimaryKey.
     * @param 	id Long
     * @return 	Clinician
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Clinician handle( FindClinicianQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getClinicianId() );
    }
    
    /**
     * Method to retrieve a collection of all Clinicians
     *
     * @param	query	FindAllClinicianQuery 
     * @return 	List<Clinician> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Clinician> handle( FindAllClinicianQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindClinician,
 * but only if the id matches
 *
 * @param		entity	Clinician
 */
	protected void emitFindClinician( Clinician entity ) {
		LOGGER.info("handling emitFindClinician" );
		
	    queryUpdateEmitter.emit(FindClinicianQuery.class,
	                            query -> query.getFilter().getClinicianId().equals(entity.getClinicianId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllClinician
	 * 
	 * @param		entity	Clinician
	 */
	protected void emitFindAllClinician( Clinician entity ) {
		LOGGER.info("handling emitFindAllClinician" );
		
	    queryUpdateEmitter.emit(FindAllClinicianQuery.class,
	                            query -> true,
	                            entity);
	}

